'use strict';
const $=id=>document.getElementById(id),canvas=$('game'),ctx=canvas.getContext('2d');
const TYPES=[
 {name:'Pulso',desc:'Rápida · crítico',cost:90,damage:15,range:160,rate:.48,color:'#b9f57e',icon:'⌖',special:'Nível 3: cada 4º tiro causa dano triplo.'},
 {name:'Canhão',desc:'Área · demolição',cost:145,damage:40,range:180,rate:1.6,color:'#ffbd78',icon:'◈',special:'Causa 35% mais dano em inimigos resfriados.'},
 {name:'Cryo',desc:'Lentidão · controle',cost:110,damage:6,range:145,rate:.75,color:'#77d8f5',icon:'❄',special:'Nível 3: reduz a velocidade em 70%.'},
 {name:'Arco',desc:'Energia · corrente',cost:175,damage:24,range:170,rate:1.05,color:'#c993ff',icon:'ϟ',special:'Salta entre até 4 inimigos no nível 3.'}
];
const PATH=[[0,330],[160,330],[160,150],[410,150],[410,490],[680,490],[680,270],[860,270],[860,330],[1000,330]];
const PADS=[[100,230],[250,230],[310,80],[490,220],[320,360],[500,410],[570,565],[600,330],[760,410],[770,190],[925,240],[215,440]];
