try{best=Number(localStorage.getItem('nexus-best'))||0;}catch{}$('record').textContent=best.toLocaleString('pt-BR');
function point(distance){let d=distance;for(let i=0;i<SEG.length;i++){if(d<=SEG[i]){let t=d/SEG[i];return {x:PATH[i][0]+(PATH[i+1][0]-PATH[i][0])*t,y:PATH[i][1]+(PATH[i+1][1]-PATH[i][1])*t};}d-=SEG[i];}return{x:1000,y:330};}
function beep(freq=440,duration=.05,type='sine',volume=.025){if(!sound)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration);}catch{}}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2500);}
function reset(){towers=[];enemies=[];shots=[];particles=[];gold=340;lives=20;wave=0;score=0;kills=0;active=false;paused=false;speed=1;pending=0;spawnClock=0;elapsed=0;selectedType=0;selectedPad=-1;ended=false;empCooldown=0;surgeCooldown=0;surgeTime=0;$('overlay').hidden=true;$('speed').textContent='1× velocidade';renderUI();}
function waveCount(w){return 6+w*2;}
function waveName(w){return w%5===0?'Assalto do chefe':w<4?'Reconhecimento':w<8?'Infiltração':w<12?'Cerco':'Ruptura total';}
function waveIntel(w){if(w>15)return 'Missão concluída';const tags=['tropas'];if(w>=3)tags.push('batedores');if(w>=6)tags.push('escudos');if(w>=7)tags.push('blindados');if(w%5===0)tags.push('CHEFE');return tags.join(' · ');}
const priorityName=p=>p==='strong'?'Mais forte':p==='fast'?'Mais rápido':'Mais avançado';
function updateAbilityUI(){$('emp').disabled=!active||paused||ended||empCooldown>0||!enemies.length;$('emp').innerHTML=empCooldown>0?`EMP <span>${Math.ceil(empCooldown)}s</span>`:'EMP <span>pronto</span>';$('surge').disabled=!active||paused||ended||surgeCooldown>0;$('surge').innerHTML=surgeTime>0?`SOBRECARGA <span>${Math.ceil(surgeTime)}s</span>`:surgeCooldown>0?`SOBRECARGA <span>${Math.ceil(surgeCooldown)}s</span>`:'SOBRECARGA <span>pronta</span>';if(document.body)document.body.classList.toggle('surge-active',surgeTime>0);}
function renderUI(){
 $('gold').textContent=gold;$('lives').innerHTML=lives+' <small>/ 20</small>';$('wave').innerHTML=String(wave).padStart(2,'0')+' <small>/ 15</small>';$('score').textContent=score.toLocaleString('pt-BR');
 $('start').disabled=active||ended;$('start').innerHTML=ended?'Missão encerrada':active?'Onda em andamento…':'Iniciar onda <span>→</span>';$('pause').disabled=!active||ended;$('pause').textContent=paused?'Continuar':'Pausar';
 $('stateLabel').textContent=ended?'OPERAÇÃO ENCERRADA':paused?'COMBATE PAUSADO':active?'CONTATO HOSTIL · DEFENDA O NÚCLEO':'AGUARDANDO SUA ESTRATÉGIA';
 $('next').textContent=wave>=15?'Última onda':String(wave+1).padStart(2,'0')+' · '+waveName(wave+1);$('count').textContent=active?(pending+enemies.length)+' restantes':wave>=15?'—':waveCount(wave+1)+' alvos';
 $('intel').textContent=active?waveIntel(wave):waveIntel(wave+1);
 updateAbilityUI();
 $('cards').innerHTML=TYPES.map((t,i)=>`<button class="tower-card ${selectedType===i?'active':''}" style="--accent:${t.color}" data-type="${i}" aria-pressed="${selectedType===i}"><span class="tower-icon">${t.icon}</span><span class="tower-copy"><strong>${t.name}</strong><small>${t.desc}</small></span><span class="price">${t.cost}</span></button>`).join('');
 $('cards').querySelectorAll('button').forEach(b=>b.onclick=()=>choose(+b.dataset.type));
 const t=towers.find(t=>t.pad===selectedPad);let panel=$('selection');
 if(t){const spec=TYPES[t.type],cost=upgradeCost(t);panel.innerHTML=`<span class="eyebrow">PLATAFORMA ${t.pad+1} · NÍVEL ${t.level}/3</span><h3 style="color:${spec.color}">${spec.name}</h3><p>Dano ${Math.round(spec.damage*damageScale(t))} · Alcance ${range(t)}<br>${spec.special}</p><div class="upgrade-row"><button id="priority">Alvo: ${priorityName(t.priority)}</button><button id="upgrade" ${t.level===3||gold<cost||ended?'disabled':''}>${t.level===3?'Nível máximo':'Evoluir · '+cost}</button><button id="sell" ${ended?'disabled':''}>Vender · ${Math.floor(t.spent*.7)}</button></div>`;$('priority').onclick=cyclePriority;$('upgrade').onclick=upgrade;$('sell').onclick=sell;
 }else if(selectedType!==null){const spec=TYPES[selectedType];panel.innerHTML=`<span class="eyebrow">CONSTRUIR · ${spec.cost} CRÉDITOS</span><h3 style="color:${spec.color}">${spec.name}</h3><p>Dano ${spec.damage} · Alcance ${spec.range}<br>${spec.special}</p>`;}else{panel.innerHTML='<span class="eyebrow">PLANEJE SUA DEFESA</span><h3>Cada posição conta.</h3><p>Selecione uma torre. Depois toque em uma plataforma numerada.</p>';}
 $('platforms').innerHTML=PADS.map((p,i)=>`<button data-pad="${i}" class="${selectedPad===i?'selected':''}" aria-label="Plataforma ${i+1}${towers.some(t=>t.pad===i)?', torre construída':''}">${i+1}</button>`).join('');$('platforms').querySelectorAll('button').forEach(b=>b.onclick=()=>selectPad(+b.dataset.pad));
}
function choose(i){if(ended)return;selectedType=i;selectedPad=-1;beep(350);renderUI();}
function selectPad(i){if(ended)return;const t=towers.find(t=>t.pad===i);if(t){selectedPad=i;selectedType=null;renderUI();return;}if(selectedType===null){toast('Escolha uma torre no arsenal.');return;}const spec=TYPES[selectedType];if(gold<spec.cost){toast('Créditos insuficientes. Elimine inimigos para ganhar mais.');return;}gold-=spec.cost;towers.push({pad:i,type:selectedType,level:1,spent:spec.cost,cooldown:.1,angle:-Math.PI/2,priority:'first',shotsFired:0});selectedPad=i;selectedType=null;burst(PADS[i][0],PADS[i][1],spec.color,18);beep(600,.13);renderUI();}
const damageScale=t=>1+(t.level-1)*.85;
const range=t=>TYPES[t.type].range+(t.level-1)*22;
const upgradeCost=t=>Math.floor(TYPES[t.type].cost*(t.level===1?.85:1.3));
function upgrade(){let t=towers.find(t=>t.pad===selectedPad);if(!t||ended||t.level>=3)return;const cost=upgradeCost(t);if(gold<cost)return;gold-=cost;t.spent+=cost;t.level++;burst(...PADS[t.pad],TYPES[t.type].color,24);beep(800,.16);renderUI();}
function sell(){const t=towers.find(t=>t.pad===selectedPad);if(!t||ended)return;gold+=Math.floor(t.spent*.7);towers=towers.filter(x=>x!==t);selectedPad=-1;renderUI();}
function cyclePriority(){const t=towers.find(t=>t.pad===selectedPad);if(!t)return;t.priority=t.priority==='first'?'strong':t.priority==='strong'?'fast':'first';beep(460,.05);renderUI();}
function startWave(){if(active||ended)return;if(!towers.length){toast('Construa pelo menos uma torre antes de iniciar.');return;}wave++;pending=waveCount(wave);spawnClock=.3;active=true;paused=false;beep(220,.3,'triangle');toast(wave%5===0?'Alerta: chefe detectado nesta onda!':'Onda '+wave+' iniciada.');renderUI();}
function spawn(){const boss=wave%5===0&&pending===1,index=waveCount(wave)-pending,fast=!boss&&wave>=3&&index%4===1,phase=!boss&&wave>=6&&index%6===3,armor=!boss&&wave>=7&&index%5===2;const hp=(40+wave*17)*Math.pow(1.095,wave-1)*(boss?8.5:armor?1.85:phase?1.2:fast?.65:1),shield=phase?hp*.75:boss?hp*.18:0;enemies.push({distance:0,x:0,y:330,hp,maxHp:hp,shield,maxShield:shield,speed:boss?40:fast?102:armor?46:65,slow:0,stun:0,boss,armor,phase,fast,color:boss?'#fa6d80':phase?'#69e6d5':armor?'#c794ef':fast?'#ffd27e':'#ee8d8d',reward:boss?110:phase?21:armor?19:fast?11:12,size:boss?24:armor?14:phase?12:10});pending--;}
function burst(x,y,color,n){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,v=20+Math.random()*100;particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:.3+Math.random()*.4,max:.7,color});}}
function hit(e,damage,sourceType=-1){if(e.hp<=0)return;let amount=damage*(e.armor?.72:1)*(sourceType===1&&e.slow>0?1.35:1);if(e.shield>0){const absorbed=Math.min(e.shield,amount);e.shield-=absorbed;amount-=absorbed;}e.hp-=amount;if(e.hp<=0){gold+=e.reward;score+=e.reward*10;kills++;burst(e.x,e.y,e.color,e.boss?32:9);beep(e.boss?120:180,.045,'triangle',.012);}}
function useEmp(){if(!active||paused||ended||empCooldown>0||!enemies.length)return;empCooldown=25;for(const e of enemies){e.shield=0;e.stun=e.boss?1.4:2.8;hit(e,e.maxHp*.06,-1);burst(e.x,e.y,'#69e6d5',7);}toast('EMP: escudos removidos e inimigos paralisados.');beep(80,.45,'sawtooth',.035);renderUI();}
function useSurge(){if(!active||paused||ended||surgeCooldown>0)return;surgeCooldown=34;surgeTime=8;toast('Sobrecarga: cadência das torres duplicada por 8 segundos.');beep(760,.35,'triangle',.03);renderUI();}
function finish(win){ended=true;active=false;paused=false;if(win)score+=lives*150;if(score>best){best=score;try{localStorage.setItem('nexus-best',String(best));}catch{}$('record').textContent=best.toLocaleString('pt-BR');}$('overlay').hidden=false;$('endLabel').textContent=win?'PROTOCOLO CONCLUÍDO':'SINAL DO NÚCLEO PERDIDO';$('endTitle').textContent=win?'Núcleo protegido.':'A defesa caiu.';$('endText').textContent=`${score.toLocaleString('pt-BR')} pontos · ${kills} inimigos eliminados · onda ${wave}/15`;beep(win?660:110,.6,'triangle');renderUI();}
function update(dt){if(paused||ended)return;elapsed+=dt;empCooldown=Math.max(0,empCooldown-dt);surgeCooldown=Math.max(0,surgeCooldown-dt);surgeTime=Math.max(0,surgeTime-dt);particles.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;});particles=particles.filter(p=>p.life>0);shots.forEach(s=>s.life-=dt);shots=shots.filter(s=>s.life>0);if(!active)return;
 spawnClock-=dt;if(pending>0&&spawnClock<=0){spawn();spawnClock=wave%5===0?.7:.8;}
 for(const e of enemies){if(e.hp<=0)continue;e.slow=Math.max(0,e.slow-dt);e.stun=Math.max(0,e.stun-dt);e.distance+=e.speed*(e.stun>0?0:e.slow>0?(e.slowPower||.48):1)*dt;Object.assign(e,point(e.distance));if(e.distance>=LENGTH){lives=Math.max(0,lives-(e.boss?5:1));e.hp=0;burst(970,330,'#ff657b',20);beep(90,.18,'sawtooth');if(lives<=0){finish(false);return;}}}
 for(const t of towers){t.cooldown-=dt;if(t.cooldown>0)continue;const [x,y]=PADS[t.pad],spec=TYPES[t.type];let targets=enemies.filter(e=>e.hp>0&&Math.hypot(e.x-x,e.y-y)<range(t));if(t.priority==='strong')targets.sort((a,b)=>(b.hp+b.shield)-(a.hp+a.shield));else if(t.priority==='fast')targets.sort((a,b)=>b.speed-a.speed);else targets.sort((a,b)=>b.distance-a.distance);const e=targets[0];if(!e)continue;t.angle=Math.atan2(e.y-y,e.x-x);t.cooldown=spec.rate/(1+(t.level-1)*.12)/(surgeTime>0?2:1);t.shotsFired=(t.shotsFired||0)+1;shots.push({x,y,tx:e.x,ty:e.y,color:spec.color,life:.16,type:t.type});let damage=spec.damage*damageScale(t);if(t.type===0&&t.level===3&&t.shotsFired%4===0){damage*=3;burst(e.x,e.y,spec.color,12);}
 if(t.type===1){enemies.filter(a=>a.hp>0&&Math.hypot(a.x-e.x,a.y-e.y)<65).forEach(a=>hit(a,damage,1));burst(e.x,e.y,spec.color,8);}else if(t.type===2){e.slow=2.4;e.slowPower=t.level===3?.30:.48;hit(e,damage,2);}else if(t.type===3){let chain=[e],cursor=e;for(let jump=0;jump<t.level;jump++){const next=enemies.filter(a=>a.hp>0&&!chain.includes(a)&&Math.hypot(a.x-cursor.x,a.y-cursor.y)<115).sort((a,b)=>b.distance-a.distance)[0];if(!next)break;shots.push({x:cursor.x,y:cursor.y,tx:next.x,ty:next.y,color:spec.color,life:.18,type:3});chain.push(next);cursor=next;}chain.forEach((a,i)=>hit(a,damage*Math.pow(.72,i),3));}else hit(e,damage,0);beep(t.type===2?950:t.type===1?100:t.type===3?720:520,.035,'sine',.008);}
 enemies=enemies.filter(e=>e.hp>0);if(pending===0&&enemies.length===0){if(wave===15){finish(true);return;}active=false;const bonus=55+wave*7;gold+=bonus;toast('Onda concluída! +'+bonus+' créditos. Prepare a defesa.');renderUI();}
}
function polygon(x,y,r,n,rotation=0){ctx.beginPath();for(let i=0;i<n;i++){const a=rotation+i*Math.PI*2/n;ctx.lineTo(x+Math.cos(a)*r,y+Math.sin(a)*r);}ctx.closePath();}
