 const selected=towers.find(t=>t.pad===selectedPad);if(selected){ctx.beginPath();ctx.arc(...PADS[selected.pad],range(selected),0,Math.PI*2);ctx.fillStyle=TYPES[selected.type].color+'0b';ctx.fill();ctx.strokeStyle=TYPES[selected.type].color+'55';ctx.lineWidth=1;ctx.setLineDash([6,6]);ctx.stroke();ctx.setLineDash([]);}
 ctx.font='11px ui-monospace,monospace';ctx.fillStyle='#77919b';ctx.textAlign='left';ctx.fillText('ENTRADA',20,391);ctx.textAlign='right';ctx.fillText('NÚCLEO',975,399);
 // The core and hostiles use geometric silhouettes for clear tactical reading.
 ctx.save();ctx.translate(958,330);ctx.rotate(elapsed*.3);polygon(0,0,34,6);ctx.fillStyle='#122d31';ctx.fill();ctx.strokeStyle=lives<7?'#ff7180':'#b9f57e';ctx.lineWidth=2;ctx.shadowBlur=18;ctx.shadowColor=ctx.strokeStyle;ctx.stroke();polygon(0,0,18,4,Math.PI/4);ctx.fillStyle=ctx.strokeStyle;ctx.fill();ctx.restore();
 PADS.forEach(([x,y],i)=>{const t=towers.find(t=>t.pad===i);ctx.save();ctx.translate(x,y);polygon(0,0,29,6,Math.PI/6);ctx.fillStyle=t?'#182b35':'#14232d';ctx.fill();ctx.lineWidth=1.5;ctx.strokeStyle=t?TYPES[t.type].color+'90':selectedType!==null?'#4b686a':'#304652';ctx.stroke();if(!t){ctx.strokeStyle=selectedType!==null?'#a4d584':'#577079';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(-7,0);ctx.lineTo(7,0);ctx.moveTo(0,-7);ctx.lineTo(0,7);ctx.stroke();}else{const spec=TYPES[t.type];ctx.rotate(t.angle);ctx.shadowColor=spec.color;ctx.shadowBlur=10;ctx.fillStyle=spec.color;polygon(0,0,t.type===1?16:13,t.type===2?6:4,t.type===1?Math.PI/4:0);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#1d343e';ctx.fillRect(-5,-5,10,10);ctx.fillStyle=spec.color;ctx.fillRect(7,-3,17+t.level*2,6);ctx.rotate(-t.angle);for(let j=0;j<t.level;j++){ctx.fillStyle=spec.color;ctx.fillRect(-t.level*4+j*8,20,5,3);}}ctx.font='10px ui-monospace,monospace';ctx.textAlign='center';ctx.fillStyle='#7e949e';ctx.fillText(String(i+1).padStart(2,'0'),0,44);ctx.restore();});
 for(const e of enemies){ctx.save();ctx.translate(e.x,e.y);ctx.rotate(e.distance*.018);if(e.shield>0){ctx.beginPath();ctx.arc(0,0,e.size+7,0,Math.PI*2);ctx.strokeStyle='#69e6d5';ctx.lineWidth=2;ctx.globalAlpha=.45+.25*Math.sin(elapsed*6);ctx.stroke();ctx.globalAlpha=1;}polygon(0,0,e.size,e.boss?6:e.armor?6:4,Math.PI/4);ctx.shadowColor=e.color;ctx.shadowBlur=e.boss?20:8;ctx.fillStyle=e.color+'33';ctx.fill();ctx.strokeStyle=e.stun>0?'#ffffff':e.slow>0?'#77d8f5':e.color;ctx.lineWidth=e.boss?3:2;ctx.stroke();ctx.shadowBlur=0;polygon(0,0,e.size*.45,4);ctx.fillStyle=e.color;ctx.fill();ctx.restore();const w=e.boss?58:32;ctx.fillStyle='#081015';ctx.fillRect(e.x-w/2,e.y-e.size-13,w,5);ctx.fillStyle=e.slow>0?'#77d8f5':e.color;ctx.fillRect(e.x-w/2,e.y-e.size-13,w*Math.max(0,e.hp/e.maxHp),5);if(e.shield>0){ctx.fillStyle='#69e6d5';ctx.fillRect(e.x-w/2,e.y-e.size-18,w*Math.max(0,e.shield/e.maxShield),3);}if(e.boss){ctx.fillStyle='#f8b6c0';ctx.font='10px ui-monospace,monospace';ctx.textAlign='center';ctx.fillText('CHEFE',e.x,e.y-e.size-23);}}
